INSERT INTO system.company_setting (id, singleton, company_name_en, company_name_ar, cr_number, vat_id, vat_enabled, vat_percentage, vat_certificate_url, default_currency, currency_decimals, address_en, address_ar, phone, country_code, mobile_number, whatsapp_phone, whatsapp_country_code, whatsapp_mobile_number, email, website, instagram_url, linkedin_url, youtube_url, map_url, bank_name, bank_iban, bank_account_number, bank_swift, time_zone, logo_url, dark_logo_url, full_logo_url, dark_full_logo_url, icon_url, dark_icon_url, stamp_url, signature_url, document_header_url, document_footer_url, payment_terms_days, invoice_prefix, invoice_next_number, receipt_prefix, receipt_next_number, ceo_name_en, ceo_name_ar, ceo_title_en, ceo_title_ar, ceo_quote_en, ceo_quote_ar, tagline_en, tagline_ar, about_text_en, about_text_ar, mission_en, mission_ar, vision_en, vision_ar, terms_en, terms_ar, rules_en, rules_ar, founded_year, city, country, primary_language, business_activity, default_discount_limit_percent, quotations_always_need_approval, theme, setup_completed_at, website_domain, admin_domain, updated_at) VALUES ('c0000000-0000-0000-0000-000000000001', 1, 'Gulf Pillars Contracting Co. W.L.L.', 'شركة أركان الخليج للمقاولات ذ.م.م', 'CR-98412-1', '200009841200002', true, 10, '/api/files/brand/stamp.png', 'BHD', 3, 'Building 312, Salman Industrial City, Hidd', 'مبنى 312، مدينة سلمان الصناعية، الحد', '+97317674400', 'BH', '17674400', '+97339674400', 'BH', '39674400', 'projects@gulfpillars.bh', 'https://gulfpillars.bh', 'https://instagram.com/gulf-pillars', 'https://linkedin.com/company/gulf-pillars', 'https://youtube.com/@gulf-pillars', 'https://maps.google.com/?q=Hidd%2C%20Bahrain', 'National Bank of Bahrain (NBB)', 'BH91NBOB00000009841200', '0009841200', 'NBOBBHBM', 'Asia/Bahrain', '/api/files/brand/logo-dark.png', '/api/files/brand/logo-light.png', '/api/files/brand/logo-dark.png', '/api/files/brand/logo-light.png', '/api/files/brand/icon-light.png', '/api/files/brand/icon-dark.png', '/api/files/brand/stamp.png', '/api/files/brand/signature.png', '/api/files/media/banners/banner-01.png', '/api/files/media/banners/banner-02.png', 30, 'GPC', 150, 'RCT', 150, 'Ebrahim Al-Doseri', 'إبراهيم الدوسري', 'Managing Director', 'العضو المنتدب', 'Precision delivery from Hidd across the GCC.', 'التميز التشغيلي من Hidd إلى جميع أسواق الخليج.', 'Civil Infrastructure, MEP & Turnkey Commercial Contracting', 'البنية التحتية المدنية والأعمال الكهروميكانيكية والمقاولات', 'Grade-A civil and MEP contractor executing industrial warehouses, commercial complexes, and municipal infrastructure across Bahrain.', 'مقاول درجة أولى للأعمال المدنية والكهروميكانيكية لتنفيذ المستودعات الصناعية والمجمعات التجارية.', 'Deliver benchmark construction services with clear bilingual accountability.', 'تقديم خدمات موثوقة ثنائية اللغة وفق أعلى معايير الجودة والالتزام.', 'To lead Bahrain''s enterprise ecosystem in construction innovation.', 'أن نكون الشريك المرجعي الأول لقطاع الأعمال في مملكة البحرين والخليج.', 'Invoices are payable within 30 calendar days in BHD. Late balances accrue documented reminders.', 'تستحق الفواتير خلال 30 يوماً بعملة BHD وفق شروط العقد المعتمد.', '10% VAT compliant with Bahrain NBR e-invoicing guidelines; signed approvals logged digitally.', 'تطبق ضريبة القيمة المضافة 10% وفق متطلبات الجهاز الوطني للإيرادات.', 2011, 'Hidd', 'BH', 'ar', 'construction', 15, false, '{"primary":"#334155","accent":"#EA580C","radius":"sm","defaultMode":"light","fonts":{"body":{"kind":"google","family":"Inter"},"heading":{"kind":"google","family":"Inter"}}}'::jsonb, '2026-01-01T00:00:00Z', 'gulfpillars.bh', 'admin.gulfpillars.bh', now()) ON CONFLICT (id) DO NOTHING;
