INSERT INTO cms.portfolio_item (id, category_id, slug, title_en, title_ar, client_name, year, subtitle_en, subtitle_ar, price, price_note_en, price_note_ar, external_url, location) VALUES ('port-1', 'pcat-cms-1', 'gulf-pillars-case-1', 'Salman Industrial City Logistics Hub', 'تشييد مركز لوجستي بمدينة سلمان الصناعية', 'Al-Jazeera Gulf Holdings W.L.L.', 2025, 'Delivered for Al-Jazeera Gulf Holdings W.L.L. across Hidd with measurable SLA benchmarks.', 'تم التنفيذ لصالح مجموعة الجزيرة الخليجية القابضة في Hidd وفق أعلى معايير الجودة والالتزام.', 29000, 'Turnkey scope including 10% NBR VAT compliance (BHD)', 'باقة تنفيذ متكاملة شاملة التقارير وضريبة القيمة المضافة', 'https://gulfpillars.bh/work/gulf-pillars-case-1', 'Hidd, Bahrain') ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.article (id, slug, title_en, title_ar, excerpt_en, excerpt_ar, body_en, body_ar, body_html_en, body_html_ar, cover_url, seo_title_en, seo_title_ar, seo_description_en, seo_description_ar, category, tags, author_name, status, publish_at, featured, created_at, updated_at) VALUES ('art-1', 'gulf-pillars-2026-outlook', 'Gulf Pillars 2026 GCC Market Outlook & Benchmarks', 'توقعات أسواق الخليج ومعايير الأداء لعام 2026 — أركان الخليج', 'Key operational benchmarks, real metrics, and 2026 guidance from Gulf Pillars in Hidd.', 'أبرز المعايير التشغيلية والأرقام الموثقة وإرشادات 2026 من أركان الخليج في Hidd.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Grade-A civil and MEP contractor executing industrial warehouses, commercial complexes, and municipal infrastructure across Bahrain. Focusing on Commercial HVAC & MEP Fit-Out, our teams help Gulf enterprises scale reliably."}]}]}'::jsonb, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"مقاول درجة أولى للأعمال المدنية والكهروميكانيكية لتنفيذ المستودعات الصناعية والمجمعات التجارية. من خلال خدمة تنفيذ أعمال التكييف والكهروميكانيك نساعد المؤسسات على النمو المستدام."}]}]}'::jsonb, '<p>Grade-A civil and MEP contractor executing industrial warehouses, commercial complexes, and municipal infrastructure across Bahrain.</p><p>Focusing on <strong>Commercial HVAC & MEP Fit-Out</strong>, our Hidd specialists help Gulf organizations standardize turnaround times and audit transparency.</p>', '<p>مقاول درجة أولى للأعمال المدنية والكهروميكانيكية لتنفيذ المستودعات الصناعية والمجمعات التجارية.</p><p>من خلال خدمة <strong>تنفيذ أعمال التكييف والكهروميكانيك</strong>، يعمل فريقنا في Hidd على توحيد سرعة التسليم ووضوح التدقيق.</p>', '/api/files/media/banners/banner-01.png', 'Gulf Pillars 2026 GCC Market Outlook & Benchmarks | Gulf Pillars', 'توقعات أسواق الخليج ومعايير الأداء لعام 2026 — أركان الخليج | أركان الخليج', 'Executive guide by Gulf Pillars covering Commercial HVAC & MEP Fit-Out benchmarks in Bahrain.', 'دليل تنفيذي من أركان الخليج حول معايير تنفيذ أعمال التكييف والكهروميكانيك في البحرين.', 'Insights', '{"construction","insights","Hidd","2026"}'::text[], 'Hana Yousef', 'draft', now() - interval '6 days', true, now() - interval '6 days', now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.faq (id, question_en, question_ar, answer_en, answer_ar, category, is_published, sort_order, created_at) VALUES ('faq-1', 'How quickly can Gulf Pillars initiate a Commercial HVAC & MEP Fit-Out engagement?', 'كم يستغرق بدء تنفيذ خدمة تنفيذ أعمال التكييف والكهروميكانيك لدى أركان الخليج؟', 'Discovery and kickoff begin within 48 hours of quotation sign-off, with a dedicated lead assigned in Hidd.', 'يبدأ التخطيط والتنفيذ خلال 48 ساعة من اعتماد عرض السعر مع تعيين مدير حساب مخصص في Hidd.', 'services', false, 1, now() - interval '45 days') ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.portfolio_item (id, category_id, slug, title_en, title_ar, client_name, year, subtitle_en, subtitle_ar, price, price_note_en, price_note_ar, external_url, location) VALUES ('port-2', 'pcat-cms-2', 'gulf-pillars-case-2', 'Adliya Medical Specialist Polyclinic', 'تجهيز وتشطيب مجمع طبي بالعدلية', 'Bahrain Bay Hospitality Group', 2026, 'Delivered for Bahrain Bay Hospitality Group across Hidd with measurable SLA benchmarks.', 'تم التنفيذ لصالح مجموعة خليج البحرين للضيافة في Hidd وفق أعلى معايير الجودة والالتزام.', 66000, 'Turnkey scope including 10% NBR VAT compliance (BHD)', 'باقة تنفيذ متكاملة شاملة التقارير وضريبة القيمة المضافة', 'https://gulfpillars.bh/work/gulf-pillars-case-2', 'Hidd, Bahrain') ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.article (id, slug, title_en, title_ar, excerpt_en, excerpt_ar, body_en, body_ar, body_html_en, body_html_ar, cover_url, seo_title_en, seo_title_ar, seo_description_en, seo_description_ar, category, tags, author_name, status, publish_at, featured, created_at, updated_at) VALUES ('art-2', 'gulf-pillars-service-standards', 'Inside Our Contracting SLA: Speed, Quality & Auditability', 'معايير اتفاقية مستوى الخدمة والجودة في تنفيذ أعمال التكييف والكهروميكانيك', 'Key operational benchmarks, real metrics, and 2026 guidance from Gulf Pillars in Hidd.', 'أبرز المعايير التشغيلية والأرقام الموثقة وإرشادات 2026 من أركان الخليج في Hidd.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Grade-A civil and MEP contractor executing industrial warehouses, commercial complexes, and municipal infrastructure across Bahrain. Focusing on Structural Concrete Foundation, our teams help Gulf enterprises scale reliably."}]}]}'::jsonb, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"مقاول درجة أولى للأعمال المدنية والكهروميكانيكية لتنفيذ المستودعات الصناعية والمجمعات التجارية. من خلال خدمة الأعمال الإنشائية والخرسانية نساعد المؤسسات على النمو المستدام."}]}]}'::jsonb, '<p>Grade-A civil and MEP contractor executing industrial warehouses, commercial complexes, and municipal infrastructure across Bahrain.</p><p>Focusing on <strong>Structural Concrete Foundation</strong>, our Hidd specialists help Gulf organizations standardize turnaround times and audit transparency.</p>', '<p>مقاول درجة أولى للأعمال المدنية والكهروميكانيكية لتنفيذ المستودعات الصناعية والمجمعات التجارية.</p><p>من خلال خدمة <strong>الأعمال الإنشائية والخرسانية</strong>، يعمل فريقنا في Hidd على توحيد سرعة التسليم ووضوح التدقيق.</p>', '/api/files/media/banners/banner-02.png', 'Inside Our Contracting SLA: Speed, Quality & Auditability | Gulf Pillars', 'معايير اتفاقية مستوى الخدمة والجودة في تنفيذ أعمال التكييف والكهروميكانيك | أركان الخليج', 'Executive guide by Gulf Pillars covering Structural Concrete Foundation benchmarks in Bahrain.', 'دليل تنفيذي من أركان الخليج حول معايير الأعمال الإنشائية والخرسانية في البحرين.', 'Operations', '{"construction","operations","Hidd","2026"}'::text[], 'Bader Ali', 'draft', now() - interval '12 days', true, now() - interval '12 days', now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.faq (id, question_en, question_ar, answer_en, answer_ar, category, is_published, sort_order, created_at) VALUES ('faq-2', 'Do all invoices include Bahrain NBR 10% VAT and Arabic breakdown?', 'هل تشمل الفواتير ضريبة القيمة المضافة 10% والتفصيل باللغتين؟', 'Yes. Every tax invoice is issued in BHD under CR CR-98412-1 and VAT ID 200009841200002 with itemized bilingual lines.', 'نعم، تصدر جميع الفواتير الضريبية بعملة BHD وفق السجل CR-98412-1 والرقم الضريبي 200009841200002.', 'billing', false, 2, now() - interval '45 days') ON CONFLICT (id) DO NOTHING;
