INSERT INTO cms.article (id, slug, title_en, title_ar, excerpt_en, excerpt_ar, body_en, body_ar, body_html_en, body_html_ar, cover_url, seo_title_en, seo_title_ar, seo_description_en, seo_description_ar, category, tags, author_name, status, publish_at, featured, created_at, updated_at) VALUES ('art-3', 'gulf-pillars-arabic-bilingual-ops', 'Why True Arabic-First Workflows Matter in Bahrain Enterprises', 'أهمية تدفقات العمل العربية المتكاملة في مؤسسات البحرين', 'Key operational benchmarks, real metrics, and 2026 guidance from Gulf Pillars in Hidd.', 'أبرز المعايير التشغيلية والأرقام الموثقة وإرشادات 2026 من أركان الخليج في Hidd.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Grade-A civil and MEP contractor executing industrial warehouses, commercial complexes, and municipal infrastructure across Bahrain. Focusing on Design & Build Commercial Contracting, our teams help Gulf enterprises scale reliably."}]}]}'::jsonb, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"مقاول درجة أولى للأعمال المدنية والكهروميكانيكية لتنفيذ المستودعات الصناعية والمجمعات التجارية. من خلال خدمة مقاولات التصميم والتنفيذ المتكامل نساعد المؤسسات على النمو المستدام."}]}]}'::jsonb, '<p>Grade-A civil and MEP contractor executing industrial warehouses, commercial complexes, and municipal infrastructure across Bahrain.</p><p>Focusing on <strong>Design & Build Commercial Contracting</strong>, our Hidd specialists help Gulf organizations standardize turnaround times and audit transparency.</p>', '<p>مقاول درجة أولى للأعمال المدنية والكهروميكانيكية لتنفيذ المستودعات الصناعية والمجمعات التجارية.</p><p>من خلال خدمة <strong>مقاولات التصميم والتنفيذ المتكامل</strong>، يعمل فريقنا في Hidd على توحيد سرعة التسليم ووضوح التدقيق.</p>', '/api/files/media/banners/banner-03.png', 'Why True Arabic-First Workflows Matter in Bahrain Enterprises | Gulf Pillars', 'أهمية تدفقات العمل العربية المتكاملة في مؤسسات البحرين | أركان الخليج', 'Executive guide b